INSERT INTO approval_rule (rule_id, rule_code, name, entity_type, min_amount, max_amount, min_duration_days, max_duration_days, required_role, min_approver_level, step_number, description) VALUES ('ARUL-01', 'APR-EXP-TIER1', 'Expense <= $100 Direct Manager Review', 'EXPENSE', 0.0, 100.0, 0, 0, 'MANAGER', 3, 1, 'Standard expense claims under $100 require immediate line manager approval.');
