INSERT INTO approval_rule (rule_id, rule_code, name, entity_type, min_amount, max_amount, min_duration_days, max_duration_days, required_role, min_approver_level, step_number, description) VALUES ('ARUL-03', 'APR-EXP-TIER2-HEAD', 'Expense $100-$1000 Step 2 Department Head Review', 'EXPENSE', 100.0, 1000.0, 0, 0, 'DIRECTOR', 4, 2, 'Claims between $100 and $1,000 require department head signoff as step 2.');
INSERT INTO approval_rule (rule_id, rule_code, name, entity_type, min_amount, max_amount, min_duration_days, max_duration_days, required_role, min_approver_level, step_number, description) VALUES ('ARUL-04', 'APR-EXP-TIER3-MGR', 'Expense $1000-$5000 Step 1 Manager', 'EXPENSE', 1000.0, 5000.0, 0, 0, 'MANAGER', 3, 1, 'High value claims require manager signoff.');
